# Esempio di script per verificare concettualmente le quattro proprietà
# di sicurezza di un plugin prima di collaudarlo nel progetto.
class_name PluginChecker
extends RefCounted


func verify_plugin_info(info: Dictionary) -> bool:
	var plugin_name: String = String(info.get("name", ""))
	var godot_version: String = String(info.get("godot_version", ""))
	var license: String = String(info.get("license", ""))
	var has_docs: bool = bool(info.get("has_documentation", false))

	print("--- Verifica plugin: %s ---" % plugin_name)
	print("Versione Godot target: %s" % godot_version)
	print("Licenza dichiarata: %s" % license)

	if license.is_empty() or license == "Sconosciuta":
		printerr("ERRORE: Licenza assente o non chiara. Non usare il plugin!")
		return false

	if not has_docs:
		printerr("ATTENZIONE: Manca la documentazione per le funzionalità chiave.")
		return false

	print("Esito positivo: il plugin può essere provato nel progetto di test.")
	return true

