extends "res://htd/htd_test.gd"


func _run_tests() -> void:
	var evaluator = await instantiate_script("res://core/plugin_evaluator.gd")
	if not check("evaluator", evaluator != null, "Lo script res://core/plugin_evaluator.gd deve potersi istanziare"):
		return

	var good_info := {
		"name": "TestPlugin",
		"license": "MIT",
		"godot_version": "4.7",
		"last_update": "2025-01-01",
		"has_documentation": true
	}
	var res_good: Dictionary = call_if_exists(evaluator, "evaluate_plugin", [good_info], {})
	check("good_approved", res_good.get("approved", false) == true, "evaluate_plugin deve approvare un plugin con tutte e 4 le caratteristiche corrette")
	check("good_passed", res_good.get("checks_passed", 0) == 4, "checks_passed deve essere 4 per un plugin valido")

	var bad_info := {
		"name": "BadPlugin",
		"license": "",
		"godot_version": "3.5",
		"last_update": "",
		"has_documentation": false
	}
	var res_bad: Dictionary = call_if_exists(evaluator, "evaluate_plugin", [bad_info], {})
	check("bad_approved", res_bad.get("approved", true) == false, "evaluate_plugin deve rifiutare un plugin non valido")
	check("bad_passed", res_bad.get("checks_passed", 4) == 0, "checks_passed deve essere 0 per un plugin privo di tutti i requisiti")

	var reg_results: Array = call_if_exists(evaluator, "load_and_evaluate_register", ["res://assets/plugin_register.json"], [])
	check("register_evaluated", reg_results.size() > 0, "load_and_evaluate_register deve restituire almeno un risultato dal registro")
	if reg_results.size() > 0 and reg_results[0] is Dictionary:
		var item: Dictionary = reg_results[0]
		check("dialogic_approved", item.get("approved", false) == true, "Il plugin nel registro deve risultare approvato")

