class_name StoryPlayer
extends Node

signal story_finished

@export var story_file_path: String = "res://story/chapters/chapter_01.json"
@export var dialogue_box: PanelContainer
@export var character_stage: CharacterStage
@export var background_display: BackgroundDisplay

var _lines: Array = []
var _labels: Dictionary = {}
var _current_line_index: int = 0
var _is_transitioning: bool = false
var _current_background: String = ""
var _current_music: String = ""
var _variables: Dictionary = {}


func _ready() -> void:
	if dialogue_box:
		dialogue_box.line_finished.connect(_on_dialogue_box_line_finished)

	if load_story(story_file_path):
		start_story()


func is_transitioning() -> bool:
	return _is_transitioning or (background_display != null and background_display.is_transitioning())


func change_background(new_texture: Texture2D, transition_type: String = "crossfade", duration: float = 0.5, mask: Texture2D = null) -> void:
	_is_transitioning = true
	if background_display:
		if transition_type == "mask":
			var used_mask: Texture2D = mask
			if not used_mask:
				used_mask = load("res://icon.svg") as Texture2D
			await background_display.transition_with_mask(new_texture, used_mask, duration)
		elif transition_type == "black":
			await background_display.transition_through_black(new_texture, duration)
		else:
			await background_display.crossfade_to(new_texture, duration)
	_is_transitioning = false


func load_story(path: String) -> bool:
	if not FileAccess.file_exists(path):
		print("Errore: file della storia non trovato: ", path)
		return false

	var file := FileAccess.open(path, FileAccess.READ)
	if not file:
		print("Errore durante l'apertura del file: ", path)
		return false

	var json := JSON.new()
	var parse_result := json.parse(file.get_as_text())
	if parse_result != OK:
		print("Errore nel parsing del JSON: ", json.get_error_message())
		return false

	var data: Dictionary = json.data
	if not data.has("lines"):
		print("Errore: la chiave 'lines' non è presente nel file JSON.")
		return false

	story_file_path = path
	_lines = data["lines"]
	_current_line_index = 0
	_index_labels()
	return true


func _index_labels() -> void:
	_labels.clear()
	for i in range(_lines.size()):
		var line_data: Dictionary = _lines[i]
		if line_data.get("type", "") == "label":
			var label_name: String = line_data.get("name", line_data.get("id", ""))
			if not label_name.is_empty():
				_labels[label_name] = i


func jump_to_label(label_name: String) -> bool:
	if not _labels.has(label_name):
		print("Errore: etichetta non trovata: ", label_name)
		return false

	_current_line_index = _labels[label_name]
	advance()
	return true


func jump_to_chapter(file_path: String, target_label: String = "") -> bool:
	if not load_story(file_path):
		return false

	if target_label.is_empty():
		start_story()
		return true

	return jump_to_label(target_label)


func start_story() -> void:
	if _lines.is_empty():
		return
	_current_line_index = 0
	_show_current_line()


func advance() -> void:
	if is_transitioning():
		return

	_current_line_index += 1
	if _current_line_index < _lines.size():
		_show_current_line()
	else:
		if dialogue_box:
			dialogue_box.clear()
		story_finished.emit()


func get_line_count() -> int:
	return _lines.size()


func restart_story() -> void:
	if _lines.is_empty():
		return
	_current_line_index = 0
	_show_current_line()


func jump_to_line(index: int) -> bool:
	if index < 0 or index >= get_line_count():
		return false
	_current_line_index = index
	_show_current_line()
	return true


func is_at_end() -> bool:
	return _current_line_index >= get_line_count()


func get_character_stage() -> CharacterStage:
	return character_stage


func get_background_display() -> BackgroundDisplay:
	return background_display


func get_save_data() -> Dictionary:
	return SaveManager.create_save_dictionary(
		SaveManager.SAVE_VERSION,
		story_file_path,
		_current_line_index,
		_variables,
		_current_background,
		_current_music
	)


func restore_from_save(data: Dictionary) -> bool:
	if data.is_empty() or not data.has("story_file"):
		return false

	var target_file: String = String(data.get("story_file", ""))
	if not load_story(target_file):
		return false

	_current_line_index = int(data.get("line_index", 0))
	_variables = data.get("variables", {}).duplicate()
	_current_background = String(data.get("background", ""))
	_current_music = String(data.get("music", ""))
	return true


func _show_current_line() -> void:
	if _current_line_index < 0 or _current_line_index >= _lines.size():
		return

	var line_data: Dictionary = _lines[_current_line_index]
	var cmd_type: String = line_data.get("type", "")

	if line_data.has("background"):
		_current_background = line_data["background"]
	if line_data.has("music"):
		_current_music = line_data["music"]

	if cmd_type == "jump_chapter":
		var target_file: String = line_data.get("target_file", "")
		var target_label: String = line_data.get("target_label", "")
		jump_to_chapter(target_file, target_label)
		return

	if cmd_type == "label":
		advance()
		return

	var speaker: String = line_data.get("speaker", "")
	var text: String = line_data.get("text", "")

	if background_display and line_data.has("background"):
		var bg_path: String = line_data["background"]
		var bg_tex: Texture2D = load(bg_path) as Texture2D
		if bg_tex:
			if dialogue_box:
				dialogue_box.clear()
			var trans_type: String = line_data.get("transition", "crossfade")
			var trans_dur: float = float(line_data.get("transition_duration", 0.5))
			var mask_tex: Texture2D = null
			if line_data.has("mask"):
				mask_tex = load(line_data["mask"]) as Texture2D
			await change_background(bg_tex, trans_type, trans_dur, mask_tex)

	if dialogue_box:
		dialogue_box.show_line(speaker, text)

	if character_stage and not speaker.is_empty():
		character_stage.focus_character(speaker.to_lower())


func _on_dialogue_box_line_finished() -> void:
	advance()

class_name SaveManager
extends Node

const TOTAL_SLOTS: int = 12
const SAVE_VERSION: int = 1


static func get_slot_json_path(slot_index: int) -> String:
	return "user://save_slot_%02d.json" % slot_index


static func get_slot_image_path(slot_index: int) -> String:
	return "user://save_slot_%02d.png" % slot_index


static func delete_save(slot_index: int) -> void:
	var json_path := get_slot_json_path(slot_index)
	var image_path := get_slot_image_path(slot_index)
	if FileAccess.file_exists(json_path):
		DirAccess.remove_absolute(json_path)
	if FileAccess.file_exists(image_path):
		DirAccess.remove_absolute(image_path)


static func create_save_dictionary(version: int, story_file: String, line_index: int, variables: Dictionary, background: String, music: String) -> Dictionary:
	return {
		"version": version,
		"story_file": story_file,
		"line_index": line_index,
		"variables": variables,
		"background": background,
		"music": music
	}


func save_game(slot_index: int, chapter_title: String, game_state_data: Dictionary, save_ui: CanvasItem = null) -> bool:
	if save_ui:
		save_ui.visible = false
		await get_tree().process_frame

	var image: Image = get_viewport().get_texture().get_image()
	image.resize(320, 180)

	if save_ui:
		save_ui.visible = true

	var image_path := get_slot_image_path(slot_index)
	var img_err := image.save_png(image_path)
	if img_err != OK:
		printerr("Impossibile salvare la miniatura: ", img_err)
		return false

	var time_dict := Time.get_datetime_dict_from_system()
	var date_string := "%02d/%02d/%04d %02d:%02d" % [
		int(time_dict["day"]),
		int(time_dict["month"]),
		int(time_dict["year"]),
		int(time_dict["hour"]),
		int(time_dict["minute"])
	]

	var save_payload := {
		"version": SAVE_VERSION,
		"chapter_title": chapter_title,
		"timestamp": date_string,
		"state": game_state_data
	}

	var json_string := JSON.stringify(save_payload, "\t")
	var json_path := get_slot_json_path(slot_index)
	var file := FileAccess.open(json_path, FileAccess.WRITE)
	if not file:
		printerr("Impossibile aprire il file di salvataggio per la scrittura.")
		return false

	file.store_string(json_string)
	return true

