extends Node

const UNLOCKS_PATH: String = "user://unlocks.json"

var unlocked_endings: Array[String] = []
var unlocked_images: Array[String] = []


func _ready() -> void:
	load_unlocks()


func unlock_ending(ending_id: String) -> void:
	if ending_id.is_empty():
		return
	if not unlocked_endings.has(ending_id):
		unlocked_endings.append(ending_id)
		save_unlocks()


func unlock_image(image_id: String) -> void:
	if image_id.is_empty():
		return
	if not unlocked_images.has(image_id):
		unlocked_images.append(image_id)
		save_unlocks()


func is_ending_unlocked(ending_id: String) -> bool:
	return unlocked_endings.has(ending_id)


func is_image_unlocked(image_id: String) -> bool:
	return unlocked_images.has(image_id)


func save_unlocks() -> void:
	var data: Dictionary = {
		"endings": unlocked_endings,
		"images": unlocked_images
	}
	var file := FileAccess.open(UNLOCKS_PATH, FileAccess.WRITE)
	if file:
		file.store_string(JSON.stringify(data, "\t"))


func load_unlocks() -> void:
	if not FileAccess.file_exists(UNLOCKS_PATH):
		return
	var file := FileAccess.open(UNLOCKS_PATH, FileAccess.READ)
	if not file:
		return
	var json_result: Variant = JSON.parse_string(file.get_as_text())
	if json_result is Dictionary:
		var dict: Dictionary = json_result
		var endings: Variant = dict.get("endings", [])
		if endings is Array:
			unlocked_endings.clear()
			for item: Variant in endings:
				unlocked_endings.append(str(item))
		var images: Variant = dict.get("images", [])
		if images is Array:
			unlocked_images.clear()
			for item: Variant in images:
				unlocked_images.append(str(item))

class_name StoryInterpreter
extends Node

@export var dialogue_box: PanelContainer
@export var character_stage: Control
@export var background_display: Control
@export var choice_menu: Control
@export var audio_manager: AudioManager


func _ready() -> void:
	if not audio_manager:
		audio_manager = get_node_or_null("../AudioManager") as AudioManager


func execute_command(command: Dictionary) -> void:
	var cmd_type: String = String(command.get("type", ""))
	match cmd_type:
		"unlock_ending":
			var item_id: String = String(command.get("id", ""))
			if not item_id.is_empty():
				UnlockManager.unlock_ending(item_id)
		"unlock_image":
			var item_id: String = String(command.get("id", ""))
			if not item_id.is_empty():
				UnlockManager.unlock_image(item_id)
		"music":
			var path: String = String(command.get("path", ""))
			var fade: float = float(command.get("fade", 1.0))
			var stream: AudioStream = load(path) as AudioStream
			if stream and audio_manager:
				audio_manager.play_music(stream, fade)
		"stop_music":
			var fade: float = float(command.get("fade", 1.0))
			if audio_manager:
				audio_manager.stop_music(fade)
		"sfx":
			var path: String = String(command.get("path", ""))
			var stream: AudioStream = load(path) as AudioStream
			if stream and audio_manager:
				audio_manager.play_sfx(stream)
		"wait":
			var duration: float = float(command.get("duration", 0.0))
			if duration > 0.0:
				await get_tree().create_timer(duration).timeout
		"shake":
			var duration: float = float(command.get("duration", 0.2))
			var strength: float = float(command.get("strength", 10.0))
			if character_stage:
				var initial_pos: Vector2 = character_stage.position
				var tween := create_tween()
				tween.tween_property(character_stage, "position", initial_pos + Vector2(strength, 0.0), duration * 0.25)
				tween.tween_property(character_stage, "position", initial_pos - Vector2(strength, 0.0), duration * 0.25)
				tween.tween_property(character_stage, "position", initial_pos, duration * 0.5)
				await tween.finished

